def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The dominant color is the background; the other color forms the enclosing lines.
    colors = {v for row in grid for v in row}
    wall = next((v for v in colors if v != wall), wall)
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] != wall and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] != wall and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
