 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    counts = {v: sum(row.count(v) for row in grid) for v in colors}
    wall = min(counts, key=counts.get)
    background = next(v for v in colors if v != wall)
    out = [row[:] for row in grid]

    # Find rectangular background cavities surrounded by wall lines. One side may
    # be the grid border; the other three sides must then be explicit wall lines.
    for top in range(h):
        for bottom in range(top + 2, h + 1):
            for left in range(w):
                for right in range(left + 2, w + 1):
                    if any(grid[r][c] != background
                           for r in range(top + 1, bottom - 1)
                           for c in range(left + 1, right - 1)):
                        continue
                    sides = []
                    if top == 0:
                        sides.append(False)
                    else:
                        sides.append(all(grid[top - 1][c] == wall
                                         for c in range(left, right)))
                    if bottom == h:
                        sides.append(False)
                    else:
                        sides.append(all(grid[bottom][c] == wall
                                         for c in range(left, right)))
                    if left == 0:
                        sides.append(False)
                    else:
                        sides.append(all(grid[r][left - 1] == wall
                                         for r in range(top, bottom)))
                    if right == w:
                        sides.append(False)
                    else:
                        sides.append(all(grid[r][right] == wall
                                         for r in range(top, bottom)))
                    if sum(sides) >= 3:
                        for r in range(top, bottom - 1):
                            for c in range(left, right - 1):
                                out[r][c] = 4
    return out


