def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    counts = {v: sum(row.count(v) for row in grid) for v in colors}
    wall = min(counts, key=counts.get)
    background = next(v for v in colors if v != wall)
    out = [row[:] for row in grid]

    # Find connected background regions. A region is a cavity only if it is a
    # filled rectangle and every edge is blocked by the frame or grid boundary.
    unseen = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == background}
    while unseen:
        start = unseen.pop()
        region = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nxt = (r + dr, c + dc)
                if nxt in unseen:
                    unseen.remove(nxt)
                    region.add(nxt)
                    q.append(nxt)

        top = min(r for r, _ in region)
        bottom = max(r for r, _ in region)
        left = min(c for _, c in region)
        right = max(c for _, c in region)
        if len(region) != (bottom - top + 1) * (right - left + 1):
            continue

        sealed = True
        for r, c in region:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if (nr, nc) in region:
                    continue
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != wall:
                    sealed = False
                    break
            if not sealed:
                break
        if sealed:
            for r, c in region:
                out[r][c] = 4
    return out


if __name__ == '__main__':
