 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Flood through background to find bounded areas; keep only exactly
    # rectangular cavities with a complete border of the non-background color.
    seen = set()
    out = [row[:] for row in grid]
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != background or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            cells = []
            touches_edge = False
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                if r == 0 or c == 0 or r == h - 1 or c == w - 1:
                    touches_edge = True
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if touches_edge:
                continue
            r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
            c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
            if len(cells) != (r1 - r0 + 1) * (c1 - c0 + 1):
                continue
            wall_color = next(grid[r][c] for r in range(h) for c in range(w)
                              if grid[r][c] != background)
            if not all(grid[r][c] == wall_color
                       for r in range(r0 - 1, r1 + 2)
                       for c in range(c0 - 1, c1 + 2)
                       if r in (r0 - 1, r1 + 1) or c in (c0 - 1, c1 + 1)):
                continue
            for r, c in cells:
                out[r][c] = 4
    return out


if __name__ == '__main__':
    test = [
        [1,1,1,1,1,7,1,1,7,7,7,7,7],
        [1,1,1,1,7,7,7,1,7,1,1,1,1],
        [1,1,1,1,7,1,7,7,7,1,1,1,1],
        [1,1,1,1,7,1,7,1,7,7,7,7,7],
        [1,1,1,1,7,1,7,1,1,1,7,1,1],
        [1,1,1,1,7,7,7,1,1,1,7,1,1],
        [1,1,1,1,1,7,1,1,1,1,7,1,1],
        [1,1,1,1,1,7,1,1,1,1,7,1,1],
        [1,1,1,1,7,7,7,7,7,1,7,1,1],
        [1,1,1,1,7,1,1,1,7,7,7,1,1],
        [1,1,1,1,7,1,1,1,7,1,7,1,1],
        [1,1,1,1,7,1,1,1,7,1,7,1,1],
        [1,1,1,1,7,7,7,7,7,1,7,1,1],
    ] + [[1,1,1,1,1,7,1,1,1,1,7,1,1] for _ in range(12)]
    result = transform(test)
    assert len(result) == 25 and all(len(row) == 13 for row in result)
    for row in result:
        print(row)
    print('25x13 verified')

# Note: filled regions are identified as fully sealed rectangular cavities.",
